  const z = View3D.zoomLevel(), zs = $("#zoomS"); if (zs && document.activeElement !== zs) zs.value = z; $("#zoomL").textContent = z.toFixed(1) + "×"; const dl = $("#hDayLen"); if (dl) dl.textContent = dayLen();
