  const tp = s.ptest[i] === 1 ? `<span class="pill">Test pending · result day ${Math.ceil(s.testAt[i] / 24)}</span>` : s.ptest[i] === 2 ? `<span class="pill coral">Tested positive · day ${Math.floor(s.ptestDay[i])}</span>` : s.ptest[i] === 3 ? `<span class="pill mint">Tested negative · day ${Math.floor(s.ptestDay[i])}</span>` : "";
