  const rows = tab === "cases" ? ids.filter(F[App.logFilter]).sort((a, b) => s.infDay[b] - s.infDay[a]) : [], sig = tab + App.logFilter + rows.length + "|" + (tab === "cases" ? Math.floor(s.t / 6) : s.t) + App.onlyInf + View3D.opt.contacts + App.actions.length;
