/* ---------- parameters ---------- */
function drawDrawer() { const s = App.sim, el = $("#drawer"), walk = s.env.type === "walk", jeep = s.env.type === "jeep", t = App.dtab || "virus";
  const tabs = { virus: ["beta", "incubation", "infectious", "untilSevere", "severeDays", "fatality", "household", "silent"], life: (jeep ? [] : ["stay", "regulars"]).concat(["sickStay", "testRate", "reportDelay"]), response: measFor(s.P.env).map(m => m.k).concat(["maskSource", "maskWearer", "shieldSource", "shieldWearer"]) }; tabs.air = ["achScale"].concat(s.env.type !== "jeep" && s.env.type !== "hospital" ? ["wind"] : [], ["coughRate"], jeep ? ["jeepTraffic"] : [], s.env.type === "hospital" ? ["ppe", "ppeBreach"] : []); if (walk) tabs.guard = ["guard", "guardNotice", "guardAccuracy", "guardDelay", "guardComply", "guardDays"];
  const tog = (k, a, b) => `<div class="seg" style="display:inline-flex;margin:0 0 10px"><button class="${s.P[k] ? "on" : ""}" data-act="dopt" data-k="${k}" data-v="1">${a}</button><button class="${s.P[k] ? "" : "on"}" data-act="dopt" data-k="${k}" data-v="0">${b}</button></div>`, a = s.P.incubation, lr = s.P.longRecovery;
  el.innerHTML = `<button class="xb" data-act="closeDrawer" aria-label="Close">${ic("x", 18)}</button><h3 class="row" style="margin-bottom:10px"><span style="color:var(--acc)">${ic("sun", 22)}</span>Parameters</h3><div class="tabs">${Object.keys(tabs).map(k => `<button class="${t === k ? "on" : ""}" data-act="dtab" data-k="${k}">${{ virus: "Virus", life: "Daily life", air: "Air", response: "Response", guard: "Guard" }[k]}</button>`).join("")}</div>
  ${(tabs[t] || tabs.virus).map(k => ctl(k, s.P[k])).join("")}
  ${t === "virus" ? `<div class="row" style="font-size:13px;gap:8px">Recovery ${tog("longRecovery", "Longer", "Standard")}</div><div class="tile" style="font-size:12px"><span>Path preview for people infected from now on</span><br>Severe case: outcome about <b style="display:inline;font-size:15px">${a + s.P.untilSevere + Math.round(s.P.severeDays * (lr ? 1.3 : 1))} days</b> after infection.<br>Mild case: recovers after about <b style="display:inline;font-size:15px">${a + Math.round(s.P.infectious * (lr ? 1.5 : 1))} days</b>.</div>` : ""}
  ${t === "air" ? `<p class="mute" style="font-size:12px;margin:0 0 10px">Two-zone air model: a breath cloud within 1.8 m in front of a speaker (near field) plus the well-mixed room air, cleared by ventilation. Doses add up through the day.</p>` : ""}${t === "air" && jeep ? `<div class="row" style="font-size:13px;gap:8px">Jeep windows ${tog("windowsOpen", "Open", "Curtains down")}</div>` : ""}
  ${t === "life" && walk ? `<div class="row" style="font-size:13px;gap:8px">Movement <div class="seg" style="display:inline-flex;margin:0 0 10px"><button class="${s.P.walkMode === "free" ? "" : "on"}" data-act="dmove" data-k="life">Daily life</button><button class="${s.P.walkMode === "free" ? "on" : ""}" data-act="dmove" data-k="free">Free walking</button></div></div>` : ""}
  ${t === "life" ? (jeep ? `<div class="row" style="font-size:13px;gap:8px">Windows ${tog("windowsOpen", "Open", "Shut")}</div><div class="row" style="font-size:13px;gap:8px">Routine ${tog("routines", "Come and go", "Stay 24 h")}</div><p class="mute" style="font-size:12px">Open windows cut the shared-air risk by more than half. The seats stay at 8 + 8, plus the driver and one passenger in front. With Stay 24 h the jeep runs a load every hour, day and night.</p>` : `<div class="row" style="font-size:13px;gap:8px">Routine ${tog("routines", "Come and go", "Stay 24 h")}</div>`) : ""}
  ${t === "response" ? `<div class="row" style="font-size:13px;gap:8px">Worn by ${tog("sickOnly", "Only the sick", "Everyone")}</div><p class="mute" style="font-size:12px">Mask and shield effect sizes are adjustable assumptions, not measured values. A shield stacks with a mask.</p>` : ""}
  ${t === "guard" ? `<p class="mute" style="font-size:12px">${GUARDS[s.P.guardType].name}. A guard only notices people with symptoms; silent cases walk past. About 1 in 100 healthy people per guard is stopped by mistake, and 3% of those test falsely positive. So far: ${s.cost.stops} stopped, ${s.cost.guardCaught} infectious people sent home, ${s.cost.falseAlarms} healthy people sent home.</p>` : ""}
  <p class="mute" style="font-size:12px;margin:8px 0 0">Changes apply to the running outbreak at once. Stage lengths affect people infected from now on.</p>`;
  bind(el, (k, v) => { s.P[k] = v; App.changes.push({ t: s.t, k, v }); if (MKEYS.includes(k)) drawCards(); if (k === "guard") View3D.setGuards(v, s.P.guardType); if (/incubation|infectious|untilSevere|severeDays/.test(k)) { const sc = el.scrollTop; drawDrawer(); el.scrollTop = sc; const inp = $("#c_" + k, el); if (inp) inp.focus(); } }); }

/* ---------- events from the engine ---------- */
function autoStop(what, who) { if (!App.autoPause) return ""; setPause(`Paused for the ${what}: ${who}. This pause is the option in the speed panel.`); return " The simulation is paused."; }
function logAction(i, text) { const s = App.sim; App.actions.push({ t: s.t, i, text }); }
let tags = []; function tag(i, text, cls) { if (cls === "say") { tags = tags.filter(t => t.i !== i || t.cls !== "say"); if (tags.filter(t => t.cls === "say").length > 3) return; } tags.push({ i, text, cls, until: performance.now() + (cls === "say" ? 1800 : 3500), x: View3D.screenOf(i) }); }
function handle(ev) { const s = App.sim, f = App.firsts, now = performance.now();
  let homeInfs = 0;
  for (const e of ev) if (e.type === "infect" && e.how && e.how.k === "home") homeInfs++;
  if (homeInfs > 0 && (!f.homeT || now - f.homeT > 6000)) {
    f.homeT = now;
    banner("Overnight family spread", `${homeInfs} ${homeInfs === 1 ? "family member was" : "family members were"} infected at home overnight by workers who returned yesterday.`, "bad", 2);
  }
  for (const e of ev) {
    if (e.type === "ptest") { const n = s.person(e.i).name; logAction(e.i, `Test result for ${n}: ${e.pos ? "POSITIVE" : "negative"}`); banner(e.pos ? "Positive" : "Negative", e.pos ? `${n}'s test came back positive${s.silent[e.i] ? ", without a single symptom" : ""}. The case is now reported; press Isolate to send ${s.gender[e.i] ? "her" : "him"} home.` : `${n}'s test came back negative${s.state[e.i] === EXPOSED ? ". The virus may have been too early to detect" : ""}.`, e.pos ? "bad" : "good", 4); if (App.sel === e.i) drawCard(true); continue; }
    if (e.type === "infect") {
      if (e.how.k === "home") continue;
      View3D.cough(e.a, e.b, e.s, e.how && e.how.k);
      if (!f.ach || now - f.ach > 3500) {
        f.ach = now;
        const isJeep = s.env.type === "jeep";
        const airy = { air: 1, pass: 1, wait: 1 }[e.how && e.how.k], title = airy ? (isJeep ? "CABIN AIR" : "SHARED AIR") : isJeep ? (s.silent[e.a] ? "JEEPNEY SPREAD!" : "COUGH IN THE JEEP!") : s.silent[e.a] ? "SILENT SPREAD!" : "ACHOO!";
        banner(title, `${interText(e.how, true)}. <span style="color:var(--acc)">${first(s, e.b)} is now exposed</span>${s.silent[e.a] ? `; ${first(s, e.a)} has no symptoms (silent spreader)` : ""}${s.masked(e.b) ? ", despite a mask" : ""}.`, "bad", 1);
      }
    }
    else if (e.type === "severe") { const p = s.person(e.i), dn = Math.round(s.day - s.infDay[e.i]), st = !f.sev ? (f.sev = 1, autoStop("first severe case", p.name)) : ""; if (!e.bed) banner("No bed free", `${p.name}, ${p.age}, is severely ill at home ${dn} days after infection. The risk of dying doubles.${st}`, "bad", 4); else if (e.overflow && !f.ovf) { f.ovf = 1; banner("Ward full", `Every ward bed is taken, so ${p.name} is being treated in a bed outside.${st}`, "warn", 4); } else if (st || !f.sev2) { f.sev2 = 1; banner("Getting worse", `${p.name}, ${p.age}, became severely ill ${dn} days after infection${e.offsite ? " and was taken to a hospital" : e.inpatient ? " in the ward bed" : " and was given a bed"}.${st}`, "bad", 4); } }
    else if (e.type === "death") { const p = s.person(e.i), st = !f.dth ? (f.dth = 1, autoStop("first death", p.name)) : ""; banner("A life lost", `${p.name}, ${p.age}, died ${Math.round(s.day - s.severeDay[e.i])} days after turning severe, ${Math.round(s.day - s.infDay[e.i])} days after infection.${st}`, "bad", 5); }
    else if (e.type === "bell") why("bell", "Class bell", "Classes change at the same moment, so hundreds of students pour out of three doors into the covered corridor. For a few minutes people are packed shoulder to shoulder and the corridor air (only about 6 air changes an hour) takes the breath of everyone passing.", "warn", [["When", fmtH(s.t % 24)], ["Corridor air", "6 changes/h"]], 25000);
    else if (e.type === "report" && !f.rep) { f.rep = 1; banner("First report", "A positive test result came back. The case is now counted, days after the infection happened.", "warn", 2); }
    else if (e.type === "quarantine" && !f.q) { f.q = 1; banner("Traced!", "Contact tracing found an exposed contact and sent them into quarantine.", "good", 2); }
    else if (e.type === "guardhome") { if (e.infected) { if (!f.gh || now - f.gh > 8000) { f.gh = now; banner("Stopped at the gate", `The guard noticed ${first(s, e.i)}'s symptoms. The rapid test was positive, so ${first(s, e.i)} went home with a quarantine letter for ${s.P.guardDays} days.`, "good", 2); } } else banner("False alarm", `${first(s, e.i)} was sent home but is not infected: a false positive. A lost income, and public trust drops.`, "warn", 3); }
    else if (e.type === "guard" && e.infected && !e.pos && !f.gm) { f.gm = 1; banner("Missed", `The guard tested ${first(s, e.i)}, but the rapid test came back negative. ${first(s, e.i)} walked in infectious.`, "bad", 2); }
    else if (e.type === "recover" && e.wasSevere && !f.rec) { f.rec = 1; banner("Pulled through", `${s.person(e.i).name} recovered and left care.`, "good", 2); }
  }
  if (s.env.type === "hospital" && s.staffAvail != null && s.staffAvail < 18 && !f.staff) { f.staff = 1; banner("Short-staffed", `Only ${s.staffAvail} of 20 doctors and nurses are fit for work, so only ${s.bedLimit} beds can be staffed.`, "warn", 3); } }
/* ---------- "What's happening?" pop-ups: explain sudden changes the player can see ---------- */
function fmtH(h) { return `${h % 12 || 12} ${h < 12 ? "AM" : "PM"}`; }
function why(key, title, text, kind, metrics, cool) { if (App.explain === false || App.mode === "replay" && App.speed > 4) return; const ex = App.ex || (App.ex = { cool: {}, seen: {} }), now = performance.now();
  if (ex.cool[key] && now < ex.cool[key]) return; if (ex.last && now - ex.last < 2500) return; ex.cool[key] = now + (cool || 45000); ex.last = now;
  const box = $("#pWhy"); if (!box) return; const life = Math.max(7, Math.min(14, text.length / 22));
  const el = document.createElement("div"); el.className = "why " + (kind || ""); el.innerHTML = `<header><i>?</i><div><div class="eyebrow">What's happening</div><b>${title}</b></div><button class="x" data-act="whyClose" aria-label="Close">×</button></header><div>${text}</div>${metrics && metrics.length ? `<div class="m">${metrics.map(([a, b]) => `<span>${a}: ${b}</span>`).join("")}</div>` : ""}<div class="t" style="animation-duration:${life}s"></div>`;
  box.prepend(el); while (box.children.length > 2) box.lastChild.remove(); setTimeout(() => el.remove(), life * 1000); }
function explainTick() { const s = App.sim; if (!s || !s.K || App.explain === false || App.screen !== "play") return; const ex = App.ex || (App.ex = { cool: {}, seen: {} }), SUBN = typeof SUB !== "undefined" ? SUB : 12, k = Math.min(SUBN, Math.floor(App.acc * SUBN)), h = s.t % 24, env = s.env;
  const stepKey = s.t * 100 + k; if (ex.key === stepKey) return; const fresh = ex.t !== s.t, pk = fresh ? -1 : ex.k; ex.key = stepKey; ex.t = s.t; ex.k = k; const crossed = x => pk < x && k >= x;
  const roomC = (q, kk) => s.kC ? s.kC[kk * (s.rooms.length || 1) + q] : 0;
  if (env.type === "jeep") { const on = s.riders && s.riders.length > 1 && k < 10, mv = on ? s.jeepMoving(k) : null, shut = !s.P.windowsOpen;
    if (on && ex.mv === true && mv === false) why("stuck", "Stuck in traffic", `The jeep stopped moving, so the breeze through its open sides is gone. The cabin's air now changes only ${Math.round(s.jeepACH(k))} times an hour instead of ${Math.round(s.jeepACH(0) > s.jeepACH(k) ? s.jeepACH(0) : (shut ? 6 : 35) * s.P.achScale)}. Everyone's breath builds up in the 14 m³ cabin: watch the haze thicken.${shut ? " With the curtains down it is even worse." : ""}`, "bad", [["Air changes", `${Math.round((shut ? 6 : 35) * s.P.achScale)} → ${Math.round(s.jeepACH(k))} per hour`], ["Riders", s.riders.length]], 30000);
    if (on && ex.mv === false && mv === true) why("moving", "Moving again", `Traffic cleared. Air rushes through the jeep again, so the cabin air is replaced ${Math.round(s.jeepACH(k))} times an hour and the haze clears within a few minutes.`, "good", [["Air changes", `${Math.round(s.jeepACH(k))} per hour`]], 30000);
    ex.mv = mv;
    if (crossed(10) && s.riders && s.riders.length > 1 && !ex.seen.para) { ex.seen.para = 1; why("para", "\"Para po!\"", "Riders tell the driver to stop and everyone gets off; the cabin empties and its air clears. The next load is already queuing at the stop, about a metre apart, for up to 15 minutes before boarding.", "", [["Ride", "45 min"], ["Queue", "15 min"]]); }
    if (k >= 1 && k < 10 && s.riders && s.riders.length > 4 && !ex.seen.board) { ex.seen.board = 1; why("board", "A full jeep", `${s.riders.length} people sit on two facing benches 0.8 m apart, knees almost touching. The person opposite is right in your breath cloud, and passing the fare hand to hand ("Bayad po") brings two faces within 40 cm.`, "warn", [["Cabin", "14 m³"], ["Facing gap", "0.8 m"]]); }
    if (ex.win != null && ex.win !== s.P.windowsOpen) why("win", s.P.windowsOpen ? "Curtains up" : "Curtains down", s.P.windowsOpen ? "The vinyl curtains are rolled up, so outside air flows through the cabin again (about 35 air changes an hour while moving)." : "The vinyl curtains are down (rain or dust). The cabin is now almost closed: about 6 air changes an hour while moving and 2.5 when stuck, so shared air becomes the main way the virus passes.", s.P.windowsOpen ? "good" : "bad", [["Air changes", s.P.windowsOpen ? "≈35/h" : "≈6/h"]], 5000);
    ex.win = s.P.windowsOpen; }
  // room air getting thick (jeep cabin, market roof, corridor, canteen, ward)
  (s.rooms || []).forEach((r, q) => { const c = roomC(q, k), half = r.cabin ? 0.02 : 0.15 / Math.sqrt(r.V), lvl = c / (c + half), keyR = "air" + q;
    if (lvl > 0.45 && !ex[keyR]) { ex[keyR] = 1; why(keyR, `Thick air in ${r.name}`, `Virus breathed out by infectious people is building up in ${r.name} faster than ventilation removes it (${Math.round(r.ach)} air changes an hour for ${Math.round(r.V)} m³). Everyone inside breathes it in, even people far from the source; their dose rings grow.`, "bad", [["Shared air", c.toFixed(3) + " quanta/m³"], ["Air changes", Math.round(r.ach) + "/h"]], 60000); }
    if (lvl < 0.2) ex[keyR] = 0; });
  // sub-step events of this moment
  for (let kk = Math.max(0, pk + 1); kk <= k; kk++) { const e = s.kev && s.kev[kk]; if (!e) continue;
    if (e.cough.length && !ex.seen.cough) { const i = e.cough.find(j => View3D.screenOf(j)); if (i != null) { ex.seen.cough = 1; why("cough", "A cough", `${first(s, i)} has symptoms and coughed: a green burst of about 25 quanta, thrown 2 m forward in a 45° cone. Anyone standing in that cone takes a large dose at once; people behind or beside are spared.`, "bad", [["Burst", "25 quanta"], ["Reach", "2 m"]]); } }
    if (env === ENVS.market && !ex.seen.shout) { const v = e.say.find(([i]) => s.role[i] === 2); if (v) { ex.seen.shout = 1; why("shout", "Vendors calling out", `Shouting "${v[1]}" pushes out about 150 quanta an hour, five times normal talking, and the breath cloud reaches 3 m. If a vendor is infectious, shoppers facing the stall get most of their dose here.`, "warn", [["Talking", "30 q/h"], ["Shouting", "150 q/h"]]); } }
    if (!ex.seen.near && e.near.some(([a, b, c]) => c > 0.03 && View3D.screenOf(a) && View3D.screenOf(b))) { ex.seen.near = 1; why("near", "Orange lines: close exposure", "An orange line joins a speaker to someone inside their breath cloud (within 1.8 m, in front of them). The brighter the line, the bigger the dose. Passing someone for a couple of seconds only draws a faint yellow line.", "", [["Near field", "≤ 1.8 m"]]); } }
  if (fresh && env.phys && env.phys.wind && h === (env.open ? env.open[0] + 1 : 8)) { const w = s.windSpd || 0; why("wind" + s.day, w < 0.6 ? "A still day" : w > 2.5 ? "A windy day" : "A light breeze", w < 0.6 ? `Almost no wind today (${w.toFixed(1)} m/s). Outdoors, breath clouds hang in front of people longer, so close conversations matter more than usual.` : `Wind today is ${w.toFixed(1)} m/s. Outdoors it thins and carries away the breath cloud in front of a speaker, so open-air chats are safer than indoors.`, w < 0.6 ? "warn" : "good", [["Wind", w.toFixed(1) + " m/s"]], 1e9); }
  if (fresh && env.type === "hospital" && !ex.seen.hepa) { ex.seen.hepa = 1; why("hepa", "Inside the ward", "HEPA filters change the ward air about 15 times an hour and pull it toward the vents on the back wall. Doctors and nurses wear N95s (the blue glow), which stop about 95% of the virus as long as the seal holds.", "good", [["Ward air", "15 changes/h"], ["N95", "95%"]]); }
  // dose and contagious-breath hints for what is on screen
  if (!ex.seen.dose && s.K) { const o = Math.min(SUBN, Math.round(App.acc * SUBN)) * s.n; for (let i = 0; i < s.n; i++) if (s.K.dose[o + i] > 0.35 && s.state[i] === HEALTHY && View3D.screenOf(i)) { ex.seen.dose = 1; tag(i, "HIGH DOSE", "bad"); why("dose", "A red dose ring", `${first(s, i)} has breathed in a lot of virus today: about a ${Math.round(100 * (1 - Math.exp(-s.K.dose[o + i])))}% chance of being infected so far. The ring under each person grows from yellow to red as their dose adds up through the day, then resets overnight.`, "bad", [["Chance so far", Math.round(100 * (1 - Math.exp(-s.K.dose[o + i]))) + "%"]]); break; } }
}
let lastT = 0, lastHud = 0;
function frame(ts) { requestAnimationFrame(frame); const s = App.sim; if (App.screen !== "play" || !s) return; const dt = Math.min(.1, (ts - lastT) / 1000); lastT = ts;
  const end = () => { App.done = true; App.running = false; App.acc = 1; syncCtl(); banner(App.mode === "replay" ? "Replay over" : "Time!", "Opening the dashboard…", "good", 6); setTimeout(() => { if (App.screen === "play" && App.done) go("results"); }, 2400); };
  if (App.running && !App.done) { App.acc += dt * App.speed * (App.skipNights ? activeHours(s) : 24) / daySeconds(); let n = 0;
    while (App.acc >= 1 && n++ < 16 && App.running) { handle(s.step()); App.acc -= 1; if (s.finished()) { end(); break; }
      if (App.skipNights) { let g = 0; while (App.running && isNight(s) && g++ < 24 && !s.finished()) handle(s.step()); if (g) App.acc = 0; if (s.finished()) { end(); break; } } }
    if (App.acc >= 1) App.acc = .99; }
  const b = App.bn; if (b && b.until && ts > b.until) { b.until = 0; b.prio = 0; $("#pBanner").style.display = "none"; }
  View3D.render(Math.min(1, App.acc)); drawLabels(); explainTick(); if (ts - lastHud > 160) { lastHud = ts; refreshHud(); } }
